/*
Milestone 2
*/

`timescale 1ns/100ps
`ifndef DISABLE_DEFAULT_NET
`default_nettype none
`endif

`include "define_state.h"
module milestone2_interface (
    input  logic        Clock_50,
    input  logic        Resetn,
    input  logic        Start,

    input  logic [15:0] SRAM_read_data,
    output logic [17:0] SRAM_address,
    output logic [15:0] SRAM_write_data,
    output logic        SRAM_we_n,

    output logic        Done
);

    //m2 state dec
    m2_state_type m2_state;

    // One-hot operation requests generated by the main FSM.
    // TODO: Pulse starts for ONE clock; do not hold throughout mega states.
    logic fetch_start, ct_start, cs_start, ws_start;
    logic fetch_done,  ct_done,  cs_done,  ws_done;

    // TODO: Add done latches for concurrent operations so a short done
    //       pulse cannot be missed while waiting for the other operation.
    logic fetch_done_seen, ct_done_seen, cs_done_seen, ws_done_seen;

    // Block identification (Y, U, V) and row/column block indices.
    logic [1:0] plane;
    logic [4:0] block_row;
    logic [3:0] block_col;

    // BRAM SIGNALS

    // Addresses (8 bits: 256 locations)
    logic [7:0] BRAM_address_a [3:0];
    logic [7:0] BRAM_address_b [3:0];

    // Write data (16 bits per location)
    logic [15:0] BRAM_write_data_a [3:0];
    logic [15:0] BRAM_write_data_b [3:0];

    // Read data (16 bits per location)
    logic [15:0] BRAM_read_data_a [3:0];
    logic [15:0] BRAM_read_data_b [3:0];

    // Write enables (active high)
    logic BRAM_we_a [3:0];
    logic BRAM_we_b [3:0];

    // BRAM 0 - T UPPER 16 BITS
    dual_port_RAM RAM_inst0 (
        .address_a (BRAM_address_a[0]),
        .address_b (BRAM_address_b[0]),
        .clock (Clock_50),
        .data_a (BRAM_write_data_a[0]),
        .data_b (BRAM_write_data_b[0]),
        .wren_a (BRAM_we_a[0]),
        .wren_b (BRAM_we_b[0]),
        .q_a (BRAM_read_data_a[0]),
        .q_b (BRAM_read_data_b[0])
    );

    // BRAM 1 - T LOWER 16 BITS
    dual_port_RAM RAM_inst1 (
        .address_a (BRAM_address_a[1]),
        .address_b (BRAM_address_b[1]),
        .clock (Clock_50),
        .data_a (BRAM_write_data_a[1]),
        .data_b (BRAM_write_data_b[1]),
        .wren_a (BRAM_we_a[1]),
        .wren_b (BRAM_we_b[1]),
        .q_a (BRAM_read_data_a[1]),
        .q_b (BRAM_read_data_b[1])
    );

    // BRAM 2 - C16 COEFFICIENTS
    dual_port_RAM RAM_inst2 (
        .address_a (BRAM_address_a[2]),
        .address_b (BRAM_address_b[2]),
        .clock (Clock_50),
        .data_a (BRAM_write_data_a[2]),
        .data_b (BRAM_write_data_b[2]),
        .wren_a (1'b0),
        .wren_b (1'b0),
        .q_a (BRAM_read_data_a[2]),
        .q_b (BRAM_read_data_b[2])
    );

    // BRAM 3 - S' AND S
    dual_port_RAM RAM_inst3 (
        .address_a (BRAM_address_a[3]),
        .address_b (BRAM_address_b[3]),
        .clock (Clock_50),
        .data_a (BRAM_write_data_a[3]),
        .data_b (BRAM_write_data_b[3]),
        .wren_a (BRAM_we_a[3]),
        .wren_b (BRAM_we_b[3]),
        .q_a (BRAM_read_data_a[3]),
        .q_b (BRAM_read_data_b[3])
    );

    // SHARED TWO-MULTIPLIER DATAPATH
    logic signed [15:0] mult1_op1, mult2_op1;
    logic signed [31:0] mult1_op2, mult2_op2;
    logic signed [47:0] mult1_result, mult2_result;

    assign mult1_result = mult1_op1 * mult1_op2;
    assign mult2_result = mult2_op1 * mult2_op2;

    logic signed [15:0] ct_mult1_op1, ct_mult2_op1;
    logic signed [31:0] ct_mult1_op2, ct_mult2_op2;
    logic signed [15:0] cs_mult1_op1, cs_mult2_op1;
    logic signed [31:0] cs_mult1_op2, cs_mult2_op2;

    always_comb begin
        mult1_op1 = '0;
        mult1_op2 = '0;
        mult2_op1 = '0;
        mult2_op2 = '0;
        case (m2_state)
            M2_CT_INITIAL, M2_MEGA_B: begin
                mult1_op1 = ct_mult1_op1;
                mult1_op2 = ct_mult1_op2;
                mult2_op1 = ct_mult2_op1;
                mult2_op2 = ct_mult2_op2;
            end
            M2_MEGA_A, M2_CS_FINAL: begin
                mult1_op1 = cs_mult1_op1;
                mult1_op2 = cs_mult1_op2;
                mult2_op1 = cs_mult2_op1;
                mult2_op2 = cs_mult2_op2;
            end
            default: ;
        endcase
    end

    // C8 COEFFICIENT SELECTION

    logic [5:0] c8_addr_1, c8_addr_2;
    logic signed [15:0] c8_coeff_1, c8_coeff_2;

    // C8 MULTIPLEXER 1

    always_comb begin
        case (c8_addr_1)

            // Row 0
            6'd0:  c8_coeff_1 = 16'sd2896;
            6'd1:  c8_coeff_1 = 16'sd2896;
            6'd2:  c8_coeff_1 = 16'sd2896;
            6'd3:  c8_coeff_1 = 16'sd2896;
            6'd4:  c8_coeff_1 = 16'sd2896;
            6'd5:  c8_coeff_1 = 16'sd2896;
            6'd6:  c8_coeff_1 = 16'sd2896;
            6'd7:  c8_coeff_1 = 16'sd2896;

            // Row 1
            6'd8:  c8_coeff_1 = 16'sd4017;
            6'd9:  c8_coeff_1 = 16'sd3405;
            6'd10: c8_coeff_1 = 16'sd2275;
            6'd11: c8_coeff_1 = 16'sd799;
            6'd12: c8_coeff_1 = -16'sd799;
            6'd13: c8_coeff_1 = -16'sd2275;
            6'd14: c8_coeff_1 = -16'sd3405;
            6'd15: c8_coeff_1 = -16'sd4017;

            // Row 2
            6'd16: c8_coeff_1 = 16'sd3784;
            6'd17: c8_coeff_1 = 16'sd1567;
            6'd18: c8_coeff_1 = -16'sd1567;
            6'd19: c8_coeff_1 = -16'sd3784;
            6'd20: c8_coeff_1 = -16'sd3784;
            6'd21: c8_coeff_1 = -16'sd1567;
            6'd22: c8_coeff_1 = 16'sd1567;
            6'd23: c8_coeff_1 = 16'sd3784;

            // Row 3
            6'd24: c8_coeff_1 = 16'sd3405;
            6'd25: c8_coeff_1 = -16'sd799;
            6'd26: c8_coeff_1 = -16'sd4017;
            6'd27: c8_coeff_1 = -16'sd2275;
            6'd28: c8_coeff_1 = 16'sd2275;
            6'd29: c8_coeff_1 = 16'sd4017;
            6'd30: c8_coeff_1 = 16'sd799;
            6'd31: c8_coeff_1 = -16'sd3405;

            // Row 4
            6'd32: c8_coeff_1 = 16'sd2896;
            6'd33: c8_coeff_1 = -16'sd2896;
            6'd34: c8_coeff_1 = -16'sd2896;
            6'd35: c8_coeff_1 = 16'sd2896;
            6'd36: c8_coeff_1 = 16'sd2896;
            6'd37: c8_coeff_1 = -16'sd2896;
            6'd38: c8_coeff_1 = -16'sd2896;
            6'd39: c8_coeff_1 = 16'sd2896;

            // Row 5
            6'd40: c8_coeff_1 = 16'sd2275;
            6'd41: c8_coeff_1 = -16'sd4017;
            6'd42: c8_coeff_1 = 16'sd799;
            6'd43: c8_coeff_1 = 16'sd3405;
            6'd44: c8_coeff_1 = -16'sd3405;
            6'd45: c8_coeff_1 = -16'sd799;
            6'd46: c8_coeff_1 = 16'sd4017;
            6'd47: c8_coeff_1 = -16'sd2275;

            // Row 6
            6'd48: c8_coeff_1 = 16'sd1567;
            6'd49: c8_coeff_1 = -16'sd3784;
            6'd50: c8_coeff_1 = 16'sd3784;
            6'd51: c8_coeff_1 = -16'sd1567;
            6'd52: c8_coeff_1 = -16'sd1567;
            6'd53: c8_coeff_1 = 16'sd3784;
            6'd54: c8_coeff_1 = -16'sd3784;
            6'd55: c8_coeff_1 = 16'sd1567;

            // Row 7
            6'd56: c8_coeff_1 = 16'sd799;
            6'd57: c8_coeff_1 = -16'sd2275;
            6'd58: c8_coeff_1 = 16'sd3405;
            6'd59: c8_coeff_1 = -16'sd4017;
            6'd60: c8_coeff_1 = 16'sd4017;
            6'd61: c8_coeff_1 = -16'sd3405;
            6'd62: c8_coeff_1 = 16'sd2275;
            6'd63: c8_coeff_1 = -16'sd799;

            default: c8_coeff_1 = 16'sd0;

        endcase
    end

    // C8 MULTIPLEXER 2

    always_comb begin
        case (c8_addr_2)

            // Row 0
            6'd0:  c8_coeff_2 = 16'sd2896;
            6'd1:  c8_coeff_2 = 16'sd2896;
            6'd2:  c8_coeff_2 = 16'sd2896;
            6'd3:  c8_coeff_2 = 16'sd2896;
            6'd4:  c8_coeff_2 = 16'sd2896;
            6'd5:  c8_coeff_2 = 16'sd2896;
            6'd6:  c8_coeff_2 = 16'sd2896;
            6'd7:  c8_coeff_2 = 16'sd2896;

            // Row 1
            6'd8:  c8_coeff_2 = 16'sd4017;
            6'd9:  c8_coeff_2 = 16'sd3405;
            6'd10: c8_coeff_2 = 16'sd2275;
            6'd11: c8_coeff_2 = 16'sd799;
            6'd12: c8_coeff_2 = -16'sd799;
            6'd13: c8_coeff_2 = -16'sd2275;
            6'd14: c8_coeff_2 = -16'sd3405;
            6'd15: c8_coeff_2 = -16'sd4017;

            // Row 2
            6'd16: c8_coeff_2 = 16'sd3784;
            6'd17: c8_coeff_2 = 16'sd1567;
            6'd18: c8_coeff_2 = -16'sd1567;
            6'd19: c8_coeff_2 = -16'sd3784;
            6'd20: c8_coeff_2 = -16'sd3784;
            6'd21: c8_coeff_2 = -16'sd1567;
            6'd22: c8_coeff_2 = 16'sd1567;
            6'd23: c8_coeff_2 = 16'sd3784;

            // Row 3
            6'd24: c8_coeff_2 = 16'sd3405;
            6'd25: c8_coeff_2 = -16'sd799;
            6'd26: c8_coeff_2 = -16'sd4017;
            6'd27: c8_coeff_2 = -16'sd2275;
            6'd28: c8_coeff_2 = 16'sd2275;
            6'd29: c8_coeff_2 = 16'sd4017;
            6'd30: c8_coeff_2 = 16'sd799;
            6'd31: c8_coeff_2 = -16'sd3405;

            // Row 4
            6'd32: c8_coeff_2 = 16'sd2896;
            6'd33: c8_coeff_2 = -16'sd2896;
            6'd34: c8_coeff_2 = -16'sd2896;
            6'd35: c8_coeff_2 = 16'sd2896;
            6'd36: c8_coeff_2 = 16'sd2896;
            6'd37: c8_coeff_2 = -16'sd2896;
            6'd38: c8_coeff_2 = -16'sd2896;
            6'd39: c8_coeff_2 = 16'sd2896;

            // Row 5
            6'd40: c8_coeff_2 = 16'sd2275;
            6'd41: c8_coeff_2 = -16'sd4017;
            6'd42: c8_coeff_2 = 16'sd799;
            6'd43: c8_coeff_2 = 16'sd3405;
            6'd44: c8_coeff_2 = -16'sd3405;
            6'd45: c8_coeff_2 = -16'sd799;
            6'd46: c8_coeff_2 = 16'sd4017;
            6'd47: c8_coeff_2 = -16'sd2275;

            // Row 6
            6'd48: c8_coeff_2 = 16'sd1567;
            6'd49: c8_coeff_2 = -16'sd3784;
            6'd50: c8_coeff_2 = 16'sd3784;
            6'd51: c8_coeff_2 = -16'sd1567;
            6'd52: c8_coeff_2 = -16'sd1567;
            6'd53: c8_coeff_2 = 16'sd3784;
            6'd54: c8_coeff_2 = -16'sd3784;
            6'd55: c8_coeff_2 = 16'sd1567;

            // Row 7
            6'd56: c8_coeff_2 = 16'sd799;
            6'd57: c8_coeff_2 = -16'sd2275;
            6'd58: c8_coeff_2 = 16'sd3405;
            6'd59: c8_coeff_2 = -16'sd4017;
            6'd60: c8_coeff_2 = 16'sd4017;
            6'd61: c8_coeff_2 = -16'sd3405;
            6'd62: c8_coeff_2 = 16'sd2275;
            6'd63: c8_coeff_2 = -16'sd799;

            default: c8_coeff_2 = 16'sd0;

        endcase
    end

    // 5. SHARED SRAM / BRAM PORT SELECTION

    // 6. MAIN FSM - LEAD-IN / MEGA STATES / LEAD-OUT
    always_ff @(posedge Clock_50 or negedge Resetn) begin
        if (!Resetn) begin
            m2_state <= M2_IDLE;
            fetch_start <= 1'b0;
            ct_start <= 1'b0;
            cs_start <= 1'b0;
            ws_start <= 1'b0;
            Done <= 1'b0;
            plane <= '0;
            block_row <= '0;
            block_col <= '0;
            fetch_done_seen <= 1'b0;
            ct_done_seen <= 1'b0;
            cs_done_seen <= 1'b0;
            ws_done_seen <= 1'b0;
        end else begin
            // TODO: Set start pulses low by default each cycle.
            // TODO: Latch done pulses while waiting for both mega tasks.
            case (m2_state)
                M2_IDLE:          begin /* TODO */ end
                M2_FETCH_INITIAL: begin /* TODO */ end
                M2_CT_INITIAL:    begin /* TODO */ end
                M2_MEGA_A:       begin /* TODO */ end
                M2_MEGA_B:       begin /* TODO */ end
                M2_CS_FINAL:     begin /* TODO */ end
                M2_WS_FINAL:     begin /* TODO */ end
                M2_FINISH:       begin /* TODO */ end
                default: m2_state <= M2_IDLE;
            endcase
        end
    end

    // FETCH S' COUNTERS

    logic [6:0] SC;       // 0-127 for Y, 0-63 for U/V, counter

    logic [7:0] RA;       // Absolute image row
    logic [7:0] CA;       // Absolute image column

    logic [3:0] cb;       // 0-13, counter
    logic [4:0] rb;       // 0-20, counter

    logic [2:0] ri;       // Row within the block
    logic [3:0] ci;       // Column within the block

    logic [17:0] row_offset;
    logic [17:0] fetch_offset;
    logic [17:0] fetch_sram_addr;

    logic [1:0] type_sel; //0 = y and 1 = u 2 = v flag

    localparam logic [17:0] Y_BASE = 18'd37632;
    localparam logic [17:0] U_BASE =    18'd75264;
    localparam logic [17:0] V_BASE = 18'd94080;
    //always comb block to handle correct addreess increments for y,u,v

    always_comb begin

        ri = 3'd0;
        ci = 4'd0;
        RA = 8'd0;
        CA = 8'd0;
        row_offset = 18'd0;
        fetch_sram_addr = 18'd0;
        fetch_offset = 18'd0;

        if (type_sel == 0) begin
            //8x16
            ri = SC[6:4];
            ci = SC[3:0];

            RA = (rb << 3) + ri;
            CA = (cb << 4) + ci;

            row_offset = ({10'b0, RA} << 8) - ({10'b0, RA} << 5);

            fetch_offset = row_offset + CA;
            fetch_sram_addr = Y_BASE + fetch_offset;

        end else begin

            ri = {1'b0, SC[5:3]};
            ci = SC[2:0];

            RA = (rb << 3) + ri;
            CA = (cb << 3) + ci;

            row_offset = ({10'b0, RA} << 7) - ({10'b0, RA} << 4);

            fetch_offset = row_offset + CA;

            if (type_sel == 2'd1)
                fetch_sram_addr = U_BASE + fetch_offset;
            else
                fetch_sram_addr = V_BASE + fetch_offset;
        end

    end

    // 7. FETCH S' FSM - SRAM -> BRAM3
    typedef enum logic [2:0] {
        FETCH_IDLE,
        FETCH_READ,
        FETCH_DELAY,
        FETCH_DELAY2
    } fetch_state_t;
    fetch_state_t fetch_state;

    always_ff @(posedge Clock_50 or negedge Resetn) begin
        if (!Resetn) begin
            fetch_state <= FETCH_IDLE;
            SC <= 7'd0;
            fetch_done <= 1'b0;
        end else begin

            case (fetch_state)
                FETCH_IDLE:    begin

                    if (fetch_start)
                        fetch_state <= FETCH_READ;

                end
                FETCH_READ:    begin /* TODO */ end

                FETCH_DELAY:    begin /* TODO */ end
                FETCH_DELAY2:    begin /* TODO */ end

                default: fetch_state <= FETCH_IDLE;
            endcase
        end
    end
    // TODO: Drive fetch_sram_addr, fetch_b3_addr/data/we from
    //       a dedicated combinational block or registered outputs.

    // 8. COMPUTE T FSM - T = S' * C
    typedef enum logic [2:0] {
        CT_IDLE,
        CT_INIT,
        CT_READ,
        CT_MAC,
        CT_STORE,
        CT_DONE
    } ct_state_t;
    ct_state_t ct_state;
    logic [3:0] ct_i, ct_j, ct_k;
    logic signed [47:0] ct_acc1, ct_acc2;

    always_ff @(posedge Clock_50 or negedge Resetn) begin
        if (!Resetn) begin
            ct_state <= CT_IDLE;
            ct_i <= '0;
            ct_j <= '0;
            ct_k <= '0;
            ct_acc1 <= '0;
            ct_acc2 <= '0;
            ct_done <= 1'b0;
        end else begin
            case (ct_state)
                CT_IDLE:  begin /* TODO */ end
                CT_INIT:  begin /* TODO */ end
                CT_READ:  begin /* TODO: BRAM read latency */ end
                CT_MAC:   begin /* TODO: shared multiplier results */ end
                CT_STORE: begin /* TODO: write both 32-bit T results */ end
                CT_DONE:  begin /* TODO */ end
                default: ct_state <= CT_IDLE;
            endcase
        end
    end
    // TODO: Drive ct_b3_addr, ct_b2_addr_a/b, CT BRAM0/1 write
    //       requests, ct_mult* operands and C8 addresses for chroma.

    // 9. COMPUTE S FSM - S = transpose(C8) * T
    typedef enum logic [2:0] {
        CS_IDLE,
        CS_INIT,
        CS_READ,
        CS_MAC,
        CS_STORE,
        CS_DONE
    } cs_state_t;
    cs_state_t cs_state;
    logic [3:0] cs_i, cs_j, cs_k;
    logic signed [47:0] cs_acc1, cs_acc2;

    always_ff @(posedge Clock_50 or negedge Resetn) begin
        if (!Resetn) begin
            cs_state <= CS_IDLE;
            cs_i <= '0;
            cs_j <= '0;
            cs_k <= '0;
            cs_acc1 <= '0;
            cs_acc2 <= '0;
            cs_done <= 1'b0;
        end else begin
            case (cs_state)
                CS_IDLE:  begin /* TODO */ end
                CS_INIT:  begin /* TODO */ end
                CS_READ:  begin /* TODO: reconstruct signed T */ end
                CS_MAC:   begin /* TODO: shared multiplier results */ end
                CS_STORE: begin /* TODO: rounding/clipping/packing */ end
                CS_DONE:  begin /* TODO */ end
                default: cs_state <= CS_IDLE;
            endcase
        end
    end
    // TODO: Drive cs_b0_addr, cs_b1_addr, cs_b3_addr/data/we,
    //       cs_mult* operands, and C8 coefficient addresses.

    // 10. WRITE S FSM - BRAM3 -> SRAM
    typedef enum logic [2:0] {
        WS_IDLE,
        WS_INIT,
        WS_READ,
        WS_WRITE,
        WS_LAST,
        WS_DONE
    } ws_state_t;
    ws_state_t ws_state;
    logic [7:0] ws_counter;

    always_ff @(posedge Clock_50 or negedge Resetn) begin
        if (!Resetn) begin
            ws_state <= WS_IDLE;
            ws_counter <= '0;
            ws_done <= 1'b0;
        end else begin
            case (ws_state)
                WS_IDLE:  begin /* TODO */ end
                WS_INIT:  begin /* TODO */ end
                WS_READ:  begin /* TODO: BRAM read latency */ end
                WS_WRITE: begin /* TODO: 2x8-bit samples per SRAM word */ end
                WS_LAST:  begin /* TODO */ end
                WS_DONE:  begin /* TODO */ end
                default: ws_state <= WS_IDLE;
            endcase
        end
    end
    // TODO: Drive ws_b3_addr, ws_sram_addr/data/write.

endmodule
